// `Lang` on its own: importing the whole `Quasar` object drags the plugin
// installer into the boot chunk (+190 KB, trips check-boot-js-budget).
import { Lang } from 'quasar';

// Quasar ships its own language packs (date-picker month and weekday names,
// "OK"/"Cancel", table paging). Without one set, they all stay English no
// matter which UI language Tolgee shows. Tolgee codes -> Quasar pack names.
const QUASAR_PACK_BY_LANGUAGE: Record<string, string> = {
  en: 'en-US',
  'pt-br': 'pt-BR',
  zh: 'zh-CN',
  ko: 'ko-KR',
};

type QuasarLangPack = { default: Parameters<typeof Lang.set>[0] };

// One lazy chunk per pack (~3 KB each), fetched only for the active language.
const packLoaders = import.meta.glob<QuasarLangPack>(
  '/node_modules/quasar/lang/*.js',
);

export function quasarPackName(language: string): string {
  const code = String(language || 'en').toLowerCase();
  return QUASAR_PACK_BY_LANGUAGE[code] ?? code;
}

export async function applyQuasarLang(language: string): Promise<boolean> {
  const loader = packLoaders[`/node_modules/quasar/lang/${quasarPackName(language)}.js`];
  if (!loader) return false;
  try {
    Lang.set((await loader()).default);
    return true;
  } catch {
    return false;
  }
}
